```mswea_bash_command
cat > /app/common.py <<'EOF'
import json,base64,secrets,re
from aiohttp import web
from db import connect,now_iso
class HTTPError(Exception):
 def __init__(self,status,msg): self.status=status; self.msg=msg
@web.middleware
async def error_middleware(request,handler):
 try: return await handler(request)
 except HTTPError as e: return web.json_response({'error':e.msg},status=e.status)
 except web.HTTPException: raise
 except Exception as e:
  return web.json_response({'error':str(e)},status=500)
async def read_json(request):
 try: return await request.json()
 except: raise HTTPError(400,'invalid json')
def user_to_json(r):
 return {k:r[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
def require_user(request):
 t=request.headers.get('Authorization','')
 if t.lower().startswith('bearer '): t=t[7:]
 if not t: raise HTTPError(401,'authentication required')
 r=connect().execute('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(t,)).fetchone()
 if not r: raise HTTPError(401,'invalid token')
 return r
def parse_limit(request):
 try: n=int(request.query.get('limit','50'))
 except: raise HTTPError(400,'invalid limit')
 if n<1 or n>200: raise HTTPError(400,'invalid limit')
 return n
def encode_cursor(n): return base64.urlsafe_b64encode(str(n).encode()).decode()
def decode_cursor(s):
 try: return int(base64.urlsafe_b64decode(s.encode()).decode())
 except: raise HTTPError(400,'invalid cursor')
def emit_event(channel_id,kind,data):
 c=connect(); row=c.execute('SELECT COALESCE(MAX(event_id),0)+1 n FROM events WHERE channel_id=?',(channel_id,)).fetchone()
 n=row['n']; c.execute('INSERT INTO events(channel_id,event_id,kind,data) VALUES(?,?,?,?)',(channel_id,n,kind,json.dumps(data)))
 return n
def broadcast_global(payload): return None
def json_user(r): return user_to_json(r)
EOF
cat > /app/routes_auth.py <<'EOF'
import secrets,re
from aiohttp import web
from db import connect,now_iso
from common import *
def setup(app):
 async def register(q):
  d=await read_json(q); u=d.get('username',''); p=d.get('password','')
  if not re.fullmatch(r'[A-Za-z0-9_]{1,32}',u) or len(p)<8: raise HTTPError(400,'invalid credentials')
  c=connect()
  try: c.execute('INSERT INTO users(username,password,display_name,created_at) VALUES(?,?,?,?)',(u,p,d.get('display_name') or u,now_iso()))
  except: raise HTTPError(409,'username already exists')
  r=c.execute('SELECT * FROM users WHERE username=?',(u,)).fetchone(); t=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(t,r['id']))
  return web.json_response({'user':user_to_json(r),'token':t},status=201)
 async def login(q):
  d=await read_json(q); r=connect().execute('SELECT * FROM users WHERE username=? AND password=?',(d.get('username'),d.get('password'))).fetchone()
  if not r: raise HTTPError(401,'wrong credentials')
  t=secrets.token_urlsafe(24); connect().execute('INSERT INTO tokens VALUES(?,?)',(t,r['id']))
  return web.json_response({'user':user_to_json(r),'token':t})
 async def me(q): return web.json_response({'user':user_to_json(require_user(q))})
 app.router.add_post('/api/auth/register',register); app.router.add_post('/api/auth/login',login); app.router.add_get('/api/auth/me',me)
EOF
ls -l /app/common.py /app/routes_auth.py
```

