p='/app/static/app.js'
s=open(p).read()
start=s.index('function renderMessages()')
end=s.index('async function react',start)
new="""function renderMessages(){
 let l=$('[data-testid=message-list');l.innerHTML='';
 if(!messages.length){l.innerHTML='<div class="empty-copy">No messages yet. Start the conversation.</div>';return}
 messages.slice().reverse().forEach(m=>{
  let row=document.createElement('article');row.dataset.testid='message';row.dataset.messageId=m.id;row.innerHTML=`<div class="avatar">${(m.author.display_name||m.author.username)[0]}</div><b>${m.author.display_name||m.author.username}</b> <time>${new Date(m.created_at).toLocaleString()}</time><div data-testid="message-body">${m.body}${m.edited_at?' <i>(edited)</i>':''}</div><div class="toolbar"><button data-action="edit">Edit</button><button data-action="delete">Delete</button><button data-testid="open-thread-btn">${m.reply_count||0} replies</button><button data-testid="reaction-button">😀</button></div><div class="reactions">${(m.reactions||[]).map(r=>`<button data-testid="reaction-chip" data-emoji="${r.emoji}">${r.emoji} ${r.count}</button>`).join('')}</div>`;
  row.querySelector('[data-testid=open-thread-btn]').onclick=()=>openThread(m);
  row.querySelector('[data-testid=reaction-button]').onclick=()=>showPicker(row,m);
  row.querySelector('[data-action=edit]').onclick=async()=>{let i=document.createElement('input');i.name='edit-body';i.value=m.body;row.querySelector('[data-testid=message-body]').replaceWith(i);i.focus();i.onkeydown=async e=>{if(e.key==='Enter'){await api('/messages/'+m.id,{method:'PATCH',body:{body:i.value}});await selectChannel(channel)}}};
  row.querySelector('[data-action=delete]').onclick=async()=>{await api('/messages/'+m.id,{method:'DELETE'});await selectChannel(channel)};
  row.querySelectorAll('[data-testid=reaction-chip]').forEach(b=>b.onclick=async()=>{await api('/messages/'+m.id+'/reactions/'+encodeURIComponent(b.dataset.emoji),{method:'DELETE'});await selectChannel(channel)});
  l.append(row)
 })
}
function showPicker(row,m){
 let p=document.createElement('div');p.dataset.testid='emoji-picker';['😀','👍','❤️','😂','🎉','🚀','😄','👏','🔥','✅'].forEach(e=>{let b=document.createElement('button');b.dataset.testid='emoji-option';b.textContent=e;b.onclick=async()=>{await api('/messages/'+m.id+'/reactions',{method:'POST',body:{emoji:e}});p.remove();await selectChannel(channel)};p.append(b)});row.append(p)
}
"""
s=s[:start]+new+s[end:]
