s=s.replace("(async()=>{if(token)try{me=(await api('/auth/me')).user;showApp()}catch(e){showAuth()}else showAuth()})();", "(async()=>{if(token)try{me=(await api('/auth/me')).user;showApp()}catch(e){showAuth()}else showAuth()})(); setInterval(()=>{if(channel)selectChannel(channel).catch(()=>{})},700);")
open(p,'w').write(s)
